import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_max_dim1(torch::Tensor x);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math_constants.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_max_dim1_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int B,
    int D1,
    int D2)
{
    const int batch = blockIdx.y;
    const int col = blockIdx.x * blockDim.x * 4 + threadIdx.x * 4;
    if (batch >= B || col >= D2) {
        return;
    }
    float acc0 = -CUDART_INF_F;
    float acc1 = -CUDART_INF;
    float acc2 = -CUDART_INF;
    float acc3 = -CUDART_INF;
    #pragma unroll 4
    for (int k = 0; k < D1; ++k) {
        const float* row = x + (static_cast<long long>(batch) * D1 + k) * D2 + col;
        if (col + 3 < D2 && (reinterpret_cast<unsigned long long>(row) & 15ULL) == 0ULL) {
            const float4 v = *reinterpret_cast<const float4*>(row);
            if (v.x != v.x || v.x > acc0) acc0 = v.x;
            if (v.y != v.y || v.y > acc1) acc1 = v.y;
            if (v.z != v.z || v.z > acc2) acc2 = v.z;
            if (v.w != v.w || v.w > acc3) acc3 = v.w;
        } else {
            const float v0 = row[0];
            if (v0 != v0 || v0 > acc0) acc0 = v0;
            if (col + 1 < D2) {
                const float v1 = row[1];
                if (v1 != v1 || v1 > acc1) acc1 = v1;
            }
            if (col + 2 < D2) {
                const float v2 = row[2];
                if (v2 != v2 || v2 > acc2) acc2 = v2;
            }
            if (col + 3 < D2) {
                const float v3 = row[3];
                if (v3 != v3 || v3 > acc3) acc3 = v3;
            }
        }
    }
    float* dst = out + static_cast<long long>(batch) * D2 + col;
    if (col + 3 < D2 && (reinterpret_cast<unsigned long long>(dst) & 15ULL) == 0ULL) {
        *reinterpret_cast<float4*>(dst) = make_float4(acc0, acc1, acc2, acc3);
    } else {
        dst[0] = acc0;
        if (col + 1 < D2) dst[1] = acc1;
        if (col + 2 < D2) dst[2] = acc2;
        if (col + 3 < D2) dst[3] = acc3;
    }
}

torch::Tensor cute_max_dim1(torch::Tensor x)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "x must be a 3D tensor");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat,
        "cute_max_dim1 currently supports float32 tensors only");

    const int B = static_cast<int>(x.size(0));
    const int D1 = static_cast<int>(x.size(1));
    const int D2 = static_cast<int>(x.size(2));

    auto x_contiguous = x.contiguous();
    auto out = torch::empty({B, D2}, x.options());

    constexpr int threads = 256;
    dim3 block(threads);
    dim3 grid((D2 + threads * 4 - 1) / (threads * 4), B);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_max_dim1_kernel<<<grid, block, 0, stream>>>(
        x_contiguous.data_ptr<float>(),
        out.data_ptr<float>(),
        B,
        D1,
        D2);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "cute_max_dim1_kernel launch failed");

    return out;
}
"""


cute_ext = load_inline(
    name="cute_max_dim1_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_max_dim1"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        if dim < 0:
            dim += 3
        if dim != 1:
            raise ValueError("ModelNew supports reduction over dimension 1")
        self.dim = dim
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_max_dim1(x)

